const body = $('Webhook Trigger').item.json.body;
if (!body.organization_id || !body.thread_id) {
  throw new Error('SCOPE_ERROR: Missing required SSOT inputs (organization_id, thread_id).');
}
return { json: body };

const strategy = $('Get Strategy').item.json[0];
const lessons = $input.item.json || [];
if (lessons.length === 0) {
  lessons.push({ lessonText: "Our recent campaigns received very low engagement. The target audience (Gen Z) seems unresponsive to long-form text. They prefer short, punchy visual hooks." });
}

const isVi = $('Webhook Trigger').item.json.body.locale === 'vi';
const lessonsText = lessons.map(l => `- ${l.lessonText}${l.metricHighlight ? ' (' + l.metricHighlight + ')' : ''}`).join('
');
const langInstruction = isVi 
  ? "IMPORTANT: Your reasoning and proposed_direction MUST be written entirely in Vietnamese (Tiếng Việt)." 
  : "IMPORTANT: Your reasoning and proposed_direction MUST be written entirely in English.";

const prompt = `You are a ruthless, data-driven Chief Marketing Officer AI.
Your current ACTIVE STRATEGY is: "${strategy.name}"
Vision: "${strategy.vision}"

Here are the recent lessons learned from the field:
${lessonsText}

Your task: Evaluate if we should PIVOT (change direction) or STAY THE COURSE.
If the lessons indicate failure or a mismatch, you MUST pivot. 
${langInstruction}

If we should pivot, respond with STRICT JSON:
{
  "should_pivot": true,
  "reasoning": "${isVi ? 'Giải thích lý do' : 'Detailed reasoning'}",
  "proposed_direction": "${isVi ? 'Hướng đi mới' : 'New direction'}"
}
If we should stay the course, respond with STRICT JSON:
{
  "should_pivot": false
}`;

return { json: { prompt, organization_id: $('Webhook Trigger').item.json.body.organization_id, thread_id: $('Webhook Trigger').item.json.body.thread_id, content_item_id: $('Webhook Trigger').item.json.body.content_item_id, department_id: $('Webhook Trigger').item.json.body.department_id, strategy_id: strategy.id } };

const response = $input.item.json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(response);
} catch (e) {
  throw new Error('STRUCTURAL_ERROR: Agent 1 did not return valid JSON.');
}
if (typeof parsed.should_pivot !== 'boolean') {
  throw new Error('STRUCTURAL_ERROR: Agent 1 output is missing the boolean `should_pivot` key.');
}
return { json: { aiResult: parsed, organization_id: $('Format Prompt').item.json.organization_id, thread_id: $('Format Prompt').item.json.thread_id, content_item_id: $('Format Prompt').item.json.content_item_id, department_id: $('Format Prompt').item.json.department_id, strategy_id: $('Format Prompt').item.json.strategy_id } };

