const response = $input.item.json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(response);
  if (typeof parsed.passed !== 'boolean' || typeof parsed.reason !== 'string') throw new Error('Missing fields');
} catch (e) {
  parsed = { passed: false, reason: 'QA_REJECT: Invalid QA Output Schema' };
}
return { json: { passed: parsed.passed, reason: parsed.reason, aiResult: $('Validate Agent 1 Output').item.json.aiResult, organization_id: $('Validate Agent 1 Output').item.json.organization_id, thread_id: $('Validate Agent 1 Output').item.json.thread_id, content_item_id: $('Validate Agent 1 Output').item.json.content_item_id, department_id: $('Validate Agent 1 Output').item.json.department_id, strategy_id: $('Validate Agent 1 Output').item.json.strategy_id } };
